frappe.listview_settings['Sales Invoice'] = {
    add_fields: ["status", "custom_payment_status"],
    get_indicator: function (doc) {
        if (doc.custom_payment_status === "Awaiting Tracking #") {
            return ["Awaiting Tracking #", "orange", "custom_payment_status"];
        } else if (doc.custom_payment_status === "Details TBC from Client") {
            return ["Details TBC from Client", "blue", "custom_payment_status"];
        } else if (doc.custom_payment_status === "Shipped") {
            return ["Shipped", "green", "custom_payment_status"];
        } else if (doc.custom_payment_status === "Not Shipped Yet") {
            return ["Not Shipped Yet", "red", "custom_payment_status"];
        } else if (doc.custom_payment_status === "Delivered") {
            return ["Delivered", "darkgreen", "custom_payment_status"];
        } else if (doc.custom_payment_status === "Issues with Delivery") {
            return ["Issues with Delivery", "red", "custom_payment_status"];
        }
    }
};

frappe.ui.form.on('Sales Invoice', {
    custom_code_percentage: function (frm) {
        calculate_promo_discount(frm);
    },
    custom_additional_discount_percentage1: function (frm) {
        calculate_additional_discount(frm);
    },
    custom_code_amount: function (frm) {
        update_total_discount(frm);
    },
    custom_additional_discount_amount1: function (frm) {
        update_total_discount(frm);
    },
    custom_location_zone: function(frm){
        frappe.db.get_value('Warehouse', {'custom_location_zone': frm.doc.custom_location_zone}, 'name')
        .then(res => {
            if (res.message && res.message.name) {
                frm.set_value('set_warehouse', res.message.name);
            }
        });
    }
});

function calculate_promo_discount(frm) {
    let percentage = frm.doc.custom_code_percentage || 0;
    let net_total = frm.doc.net_total || 0;

    let promo_amount = (net_total * percentage) / 100;  // Calculate promo discount
    frm.set_value('custom_code_amount', promo_amount);

    update_total_discount(frm); // Recalculate total discount
}

function calculate_additional_discount(frm) {
    let percentage = frm.doc.custom_additional_discount_percentage1 || 0;
    let net_total = frm.doc.net_total || 0;

    let additional_discount = (net_total * percentage) / 100;  // Calculate additional discount
    frm.set_value('custom_additional_discount_amount1', additional_discount);

    update_total_discount(frm); // Recalculate total discount
}

function update_total_discount(frm) {
    let promo_amount = frm.doc.custom_code_amount || 0;
    let additional_discount = 0;

    let total_discount = promo_amount + additional_discount;  // Sum both discounts
    frm.set_value('discount_amount', total_discount); // Update hidden discount field

    frm.refresh_field('discount_amount');
}


