frappe.ui.form.on("Sales Invoice", {
    validate: function(frm){
        frm.doc.items.map(row=>{
            frappe.model.set_value(row.doctype, row.name, 'expense_account', "Cost of Goods Sold - OMG");
        });
    }
});

frappe.ui.form.on("Sales Invoice Item", {
    item_code: function(frm, cdt, cdn){
        let row = locals[cdt][cdn];
        frappe.call({
            method:"get_item_quantity_factor",
            args: {item_code:row.item_code},
            callback: function(r){
                let factor = r.message;
                frappe.model.set_value(cdt, cdn, "qty_factor", factor);
            }
        });
    },
    quantity_in_units: function(frm, cdt, cdn){
        let row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, "qty", row.quantity_in_units /* / row.qty_factor*/);
    }
});

frappe.ui.form.on('Lead', {
  refresh: function (frm) {
    if (!frm.is_new()) {
      frm.set_df_property('custom_send_samples', 'options',
        `<button class="btn btn-primary" id="create_stock_entry_btn">
           Send Sample
         </button>`
      );

      setTimeout(() => {
        $('#create_stock_entry_btn').on('click', async function () {
          if (!frm.doc.custom_sample || frm.doc.custom_sample.length === 0) {
            frappe.msgprint(__('No items in custom_sample table.'));
            return;
          }

          if (!frm.doc.custom_warehouse) {
            frappe.msgprint(__('Please select a warehouse.'));
            return;
          }

          const stock_entry = frappe.model.get_new_doc('Stock Entry');
          stock_entry.stock_entry_type = 'Material Issue';
          stock_entry.from_warehouse = frm.doc.custom_warehouse;
          stock_entry.custom_reference_lead = frm.doc.name;

          for (const sample of frm.doc.custom_sample) {
            if (!sample.item_code || !sample.qty) continue;

            const uom = await get_uom(sample.item_code);

            const item = frappe.model.add_child(stock_entry, 'Stock Entry Detail', 'items');
            item.item_code = sample.item_code;
            item.qty = sample.qty;
            item.s_warehouse = frm.doc.custom_warehouse;
            item.uom = uom;
            item.stock_uom = uom;
            item.conversion_factor = 1;
            item.transfer_qty = sample.qty;
          }

          frappe.model.sync(stock_entry);
          frappe.set_route('Form', 'Stock Entry', stock_entry.name);
        });
      }, 100);
    }
  },

  before_save: function (frm) {
    let total = 0;
    for (let row of frm.doc.custom_sample) {
      total += row.qty;
    }
    frm.set_value("custom_total_quantity", total);
  }
});

async function get_uom(item_code) {
  try {
    const res = await frappe.db.get_value('Item', item_code, 'stock_uom');
    return res.message.stock_uom || 'Nos';
  } catch (err) {
    return 'Nos';
  }
}

frappe.ui.form.on("Stock Entry", {
    onload: function(frm) {
        if (frm.is_new()) {
            frm.clear_table('transfer_expenses');
        }
        // stock expenses change the delete button behavior
        if(frm.doc.docstatus === 1)
		    changeEventListener(frm);
    },
	refresh(frm) {
		frm.set_query("cash_account", "transfer_expenses", () => {
			return {
				filters: {
					account_type: ["in",["Bank","Cash", "Current Liability"]],
					company: frm.doc.company,
					is_group: 0
				}
			};
		});
		frm.set_query("expense_account", "transfer_expenses", () => {
			return {
				filters: {
					root_type: "Expense",
					company: frm.doc.company,
					is_group: 0
				}
			};
		});
		// stock expenses change the delete button behavior
		if(frm.doc.docstatus === 1)
		    changeEventListener(frm);
	}
});

function changeEventListener(frm){
    if(frm.fields_dict.transfer_expenses.grid.grid_buttons.find(".grid-remove-rows[data-action='delete_rows']").length){
        frm.fields_dict.transfer_expenses.grid.grid_buttons.find(".grid-remove-rows").removeAttr("data-action");
        frm.fields_dict.transfer_expenses.grid.grid_buttons.find(".grid-remove-rows").click(() => {
            let grid = frm.fields_dict.transfer_expenses.grid,
                jvs = grid.get_selected_children().filter(row=>row.journal_voucher).map(row=>row.journal_voucher);
            if(jvs.length){
                frappe.confirm("Are You sure you want To delete these rows <br>The linked Journal Vouchers will be Cancelled!",
                    () =>{
                        grid.delete_rows();
                        setTimeout(async ()=>{
                            await frm.save("Update");
                            jvs.map(jv=>{
                                frappe.call({
                                    method: "mcancel_or_delete_doc",
                                    args:{
                                        action: "cancel",
                                        doctype: "Journal Entry",
                                        docname:  jv,
                                    }
                                });
                            });
                        }, 500);
                    },
                ()=>{});
            } else {
                grid.delete_rows();
            }
    	});
    }
}

frappe.ui.form.on("Stock Entry", {
    validate: function(frm){
        frm.doc.items.map(row=>{
            frappe.model.set_value(row.doctype, row.name, 'expense_account', "Stock Adjustment - OMG");
        });
    }
});

frappe.ui.form.on('Email Account', {
	refresh(frm) {
// 		if (frm.doc.enable_outgoing) {
			site_name = window.location.hostname;
			uninstall_link = `https://cloud.frappe.io/dashboard/sites/${site_name}/apps`;
			eds_a_tag = `<a style='text-decoration: underline;' href='https://cloud.frappe.io/marketplace/apps/email_delivery_service'>Email Delivery Service</a>`;
			//make a head request to /api/method/ping and check if response has server header set as 'Frappe Cloud'
			is_frappe_cloud = fetch('/api/method/ping', { method: 'HEAD' }).then(
				(response) => {
					if (response.headers.get('server') === 'Frappe Cloud') {
						return true;
					}
					return false;
				},
			);
			uninstall_a_tag = `<a style='text-decoration: underline;' href='${uninstall_link}'>uninstall the app</a>`;
			if (!is_frappe_cloud) {
				uninstall_a_tag = 'uninstall the app';
			}
			frm.dashboard.set_headline_alert(
				__(
					`You have ${eds_a_tag} app installed due to which emails won't be sent from this account. Please ${uninstall_a_tag} to use current Email Account for sending.`,
				),
				'yellow',
			);
// 		}
	},
});
